    public void normalize_ShouldReturnEmptyString_WhenInputIsNull() throws Throwable {
        // Given: A StringNormalizer instance and null input
        StringNormalizer normalizer = new StringNormalizer();

        // When: normalize is called with null
        String result = normalizer.normalize(null);

        // Then: An empty string should be returned
        assertEquals("", result);
    }

    @Test(timeout = 4000)
    public void normalize_ShouldReturnNormalizedString_WhenInputContainsSpecialCharacters() throws Throwable {
        // Given: A StringNormalizer instance and a string with special characters
        StringNormalizer normalizer = new StringNormalizer();
        String input = "t#8";

        // When: normalize is called
        String result = normalizer.normalize(input);

        // Then: The normalized string should be returned
        assertEquals("t#8", result);
    }
}
